import pyomo.environ as pyo

DATA = {
    "cakes": ["crepe", "sponge", "birthday"],
    "resources": ["batter", "milk"],
    "resource_available": {
        "batter": 20000,
        "milk": 14000,
    },
    "usage": {
        "crepe":    {"batter": 400, "milk": 200},
        "sponge":   {"batter": 500, "milk": 300},
        "birthday": {"batter": 450, "milk": 350},
    },
    "profit": {
        "crepe": 12,
        "sponge": 10,
        "birthday": 15,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.CAKES = pyo.Set(initialize=d["cakes"])
    model.RESOURCES = pyo.Set(initialize=d["resources"])

    # Bundles of cakes to produce (whole cakes, nonnegative)
    model.x = pyo.Var(model.CAKES, within=pyo.NonNegativeIntegers)

    # Objective: maximize total profit
    def profit_rule(m):
        return sum(d["profit"][c] * m.x[c] for c in m.CAKES)
    model.obj = pyo.Objective(rule=profit_rule, sense=pyo.maximize)

    # "20000 grams of batter and 14000 grams of milk" availability limits
    def supply_rule(m, r):
        return sum(d["usage"][c][r] * m.x[c] for c in m.CAKES) <= d["resource_available"][r]
    model.resource_limit = pyo.Constraint(model.RESOURCES, rule=supply_rule)

    return model
